#pragma once
// A world's dimensions and what generates each (the game's WorldGenSettings, LevelStem and DimensionType): read from
// the save, with the data packs' own dimensions, so every dimension is generated by its real generator.
#include "worldgen/datapack.h"

namespace wg {

struct DimensionSpec {
    std::string name;          // "minecraft:the_nether"
    nlohmann::json generator;  // the LevelStem's generator: {"type": "minecraft:noise" | "minecraft:flat" | ...}
    int minY = -64, height = 384;  // the dimension type's build range
    bool hasCeiling = false;
};

struct WorldGenSettings {
    i64 seed = 0;
    bool generateStructures = true;
    std::vector<DimensionSpec> dimensions;
    const DimensionSpec* find(std::string_view name) const;
};

// The save's settings (data/minecraft/world_gen_settings.dat, or level.dat's WorldGenSettings in older saves). The
// data packs' dimension/ entries are added (and replace the saved ones, like the game's registry), and vanilla
// dimensions the save lacks come from world_preset/normal. False if the save has no settings.
bool readWorldGenSettings(const fs::path& saveDir, const DataPack& data, WorldGenSettings& out);
// A new world's: world_preset/normal (or `preset`) plus the data packs' dimensions.
WorldGenSettings defaultWorldGenSettings(const DataPack& data, i64 seed, std::string_view preset = "minecraft:normal");

}  // namespace wg
